"""
Генерация данных для категории "Тайский для жизни" (course_l_1 … course_l_15).
Пишет напрямую в steps.json, lessons.json, taika_basa_course.json.
Без дублей с "База от Тайки". Spec: phonetic ASCII '-', стрелки, без type, ru до 60 символов.
"""
import json
import os

TAIKA_ROOT = os.path.join(os.path.dirname(__file__), "..")
STEPS_PATH = os.path.join(TAIKA_ROOT, "steps.json")
LESSONS_PATH = os.path.join(TAIKA_ROOT, "lessons.json")
COURSE_PATH = os.path.join(TAIKA_ROOT, "taika", "Resourses", "taika_basa_course.json")
LIFE_IDS = {"course_l_" + str(i) for i in range(1, 16)}


def item(order, kind, **kwargs):
    out = {"order": order, "kind": kind}
    if kind in ("word", "phrase", "casual"):
        out["ru"] = kwargs.get("ru", "")
        out["thai"] = kwargs.get("thai", "")
        out["phonetic"] = kwargs.get("phonetic", "")
        if kwargs.get("tip"):
            out["tip"] = kwargs["tip"]
    elif kind == "tip":
        out["text"] = kwargs.get("text", "")
    return out


